test('Both includes text and interword spaces (v2 regression)',()=>assert.deepEqual(indices(api.collectUnits(data('a b c'),s({target:'both'}))),[0,1,2,3,4]));
test('Letters tracking omits outgoing glyphs and preserves actual word-gap boundaries',()=>assert.deepEqual(indices(api.collectUnits(data('abc def'),s())),[0,1,4,5,6]));
test('Letters on nontracking properties still includes every letter',()=>assert.deepEqual(indices(api.collectUnits(data('abc def'),s({property:'pointSize'}))),[0,1,2,4,5,6]));
test('Spaces mode preserves every letter and groups adjacent gaps',()=>assert.deepEqual(indices(api.collectUnits(data('a  b c'),s({target:'spaces'}))),[1,2,4]));
test('Both character mode counts letters and individual spaces in order',()=>assert.deepEqual(indices(api.collectUnits(data('a  b c'),s({target:'both',mode:'character'}))),[0,1,2,3,4,5]));
test('Both line mode includes internal spaces but excludes line-ending spaces',()=>{const d=data('abc def ghi');d.lines=[{start:0,end:7},{start:8,end:10}];const u=api.collectUnits(d,s({mode:'line',target:'both'}));assert.deepEqual(indices([u[0]]),[0,1,2,3,4,5,6]);});
test('letters selected up to a space boundary omit outgoing tracking even outside the scope',()=>{const d=data('abc');d.after='space';assert.deepEqual(indices(api.collectUnits(d,s())),[0,1]);});
test('custom curves support several peaks and shifted peaks',()=>{const points=[{x:0,y:0},{x:.2,y:1},{x:.4,y:0},{x:.7,y:.8},{x:1,y:0}];for(const p of points)assert.ok(Math.abs(api.customValue(p.x,points,true)-p.y)<1e-9);assert.ok(api.customValue(.2,points,true)>api.customValue(.5,points,true));});
test('smooth custom interpolation stays bounded without overshooting',()=>{const points=[{x:0,y:.3},{x:.1,y:1},{x:.3,y:0},{x:.8,y:1},{x:1,y:.4}];for(let i=0;i<=1000;i++){const y=api.customValue(i/1000,points,true);assert.ok(y>=0&&y<=1);}});
test('linear custom interpolation is exact',()=>assert.equal(api.customValue(.25,[{x:0,y:0},{x:.5,y:1},{x:1,y:0}],false),.5));
test('dragging locks endpoint X and prevents point crossover',()=>{const p=[{x:0,y:0},{x:.5,y:1},{x:1,y:0}];api.movePoint(p,0,.5,.4);api.movePoint(p,1,2,2);assert.deepEqual(plain(p[0]),{x:0,y:.4});assert.equal(p[1].x,.995);assert.equal(p[1].y,1);});
test('adding control points keeps the curve ordered and deduplicates close points',()=>{const p=[{x:0,y:0},{x:1,y:1}];api.addPoint(p,.3,.8);assert.equal(p[1].x,.3);api.addPoint(p,.301,.2);assert.equal(p.length,3);});
test('nontracking properties preserve fractional values',()=>{const d=api.buildDistribution(3,s({property:'pointSize',min:12.1,max:12.2}));assert.deepEqual(Array.from(d.values),[12.1,12.15,12.2]);assert.deepEqual(Array.from(api.buildDistribution(3,s({min:0,max:3})).values),[0,2,3]);});
test('stepped bells remain symmetric for uneven counts',()=>{for(let n=3;n<35;n++)for(let steps=3;steps<=n;steps++){const a=Array.from(api.buildDistribution(n,s({curve:'gaussian',steps})).values);assert.deepEqual(a,a.slice().reverse());}});
test('property metadata includes all requested targets and native ranges',()=>{for(const id of ['tracking','pointSize','baselineShift','horizontalScale','verticalScale','characterRotation','skew','strokeWeight','strokeColor','strokeTint'])assert.ok(api.propertyInfo(id).high>api.propertyInfo(id).low);assert.equal(api.propertyInfo('designAxes',{name:'Weight',min:100,max:900}).high,900);});
