test('adaptive line mode recalculates until the resulting line boundaries agree',()=>{let state=0,applies=0;const base=data('abc def ghi');const layouts=[[{start:0,end:7},{start:8,end:10}],[{start:0,end:3},{start:4,end:7},{start:8,end:10}]];const p=api.settleLines({capture(){return{...base,lines:layouts[state]};},restore(){},apply(){applies++;state=1;},recompose(){}},s({mode:'line',target:'both'}));assert.equal(p.units.length,3);assert.equal(p.passes,2);assert.equal(applies,2);});
