test('variable axis uses discovered font ranges and explicit axis selection',()=>{const h=host('alpha beta');const p=new api.PreviewSession(h.target);p.preview(s({property:'designAxes',axisName:'Weight',min:100,max:900}));assert.equal(h.chars[0].designAxes[0],100);assert.equal(h.chars.at(-1).designAxes[0],900);p.rollback();assert.ok(h.chars.every(c=>c.designAxes[0]===400));});
