test('characters restart their full curve inside each word',()=>{const p=api.makePlan(data('abcd xy'),s({property:'pointSize',mode:'character',restart:'word',min:10,max:30}));assert.equal(p.groups.length,2);assert.deepEqual(plain(p.distribution.values),[10,16.667,23.333,30,10,30]);});
test('tracking letters still preserve outgoing gaps when restarting per word',()=>{const p=api.makePlan(data('abcd xy'),s({mode:'character',restart:'word'}));assert.deepEqual(plain(p.distribution.values),[0,50,100,0,100]);assert.deepEqual(indices(p.units),[0,1,2,5,6]);});
test('words restart a complete ramp in each sentence',()=>{const p=api.makePlan(data('one two three. four five six.'),s({restart:'sentence'}));assert.equal(p.groups.length,2);assert.deepEqual(plain(p.distribution.values),[0,50,100,0,50,100]);});
test('sentence units restart per paragraph with independent sample counts',()=>{const p=api.makePlan(data('One. Two!\rThree? Four. Five.'),s({mode:'sentence',restart:'paragraph'}));assert.deepEqual(Array.from(p.groups,g=>g.count),[2,3]);assert.deepEqual(plain(p.distribution.values),[0,100,0,50,100]);});
test('paragraph units skip empty paragraphs without losing scope bounds',()=>{const p=api.makePlan(data('alpha beta\r\rdelta epsilon\rfinal'),s({mode:'paragraph'}));assert.equal(p.units.length,3);assert.deepEqual(plain(p.distribution.values),[0,50,100]);assert.equal(new Set(indices(p.units)).size,indices(p.units).length);});
test('sentence recognition handles decimals, initials, abbreviations, quotes and Unicode terminals',()=>{const p=api.makePlan(data('Dr. A. Smith paid 3.14. “Done!” Next? 你好。 再见！'),s({mode:'sentence'}));assert.equal(p.units.length,5);});
test('sentence recognition treats paragraph breaks as sentence boundaries',()=>{const p=api.makePlan(data('No punctuation\rStill a sentence'),s({mode:'sentence'}));assert.equal(p.units.length,2);});
test('frame units distribute over visible linked frames and exclude overset',()=>{const d=data('alpha beta gamma delta extra');d.frames=[{start:0,end:10,id:8},{start:11,end:21,id:9}];const p=api.makePlan(d,s({mode:'frame',target:'both'}));assert.equal(p.units.length,2);assert.deepEqual(plain(p.distribution.values),[0,100]);assert.ok(indices(p.units).every(x=>x<=21));});
test('word curves restart per frame and omit the uncomposed tail',()=>{const d=data('aa bb cc dd ee');d.frames=[{start:0,end:5,id:8},{start:6,end:11,id:9}];const p=api.makePlan(d,s({restart:'frame',target:'both'}));assert.deepEqual(plain(p.distribution.values),[0,100,0,100]);assert.ok(indices(p.units).every(x=>x<12));});
test('units crossing resulting-line groups split at the boundary without double application',()=>{const d=data('abcdefgh ij kl');d.lines=[{start:0,end:3},{start:4,end:8},{start:9,end:13}];const p=api.makePlan(d,s({restart:'line',target:'both',property:'pointSize',min:10,max:30}));assert.deepEqual(Array.from(p.groups,g=>g.count),[1,1,2]);assert.deepEqual(plain(p.distribution.values),[10,10,10,30]);const all=indices(p.units);assert.equal(new Set(all).size,all.length);assert.ok(!all.includes(8),'Exclude the trailing space at a line edge');});
test('step limits and bell sampling are calculated independently for every group',()=>{const p=api.makePlan(data('aa bbbbb ccccccc'),s({mode:'character',restart:'word',property:'pointSize',curve:'gaussian',steps:5,min:10,max:30}));assert.deepEqual(Array.from(p.groups,g=>g.distribution.steps),[2,5,5]);assert.deepEqual(plain(p.groups[0].distribution.values),[10,10]);assert.equal(Math.max(...p.groups[1].distribution.values),30);assert.equal(Math.max(...p.groups[2].distribution.values),30);});
test('frame ownership is part of the adaptive composition key',()=>{const d=data('alpha beta');d.frames=[{start:0,end:9,id:8}];const a=api.geometryKey(d);d.frames=[{start:0,end:4,id:8},{start:5,end:9,id:9}];assert.notEqual(api.geometryKey(d),a);});
test('character per resulting line recomposes and reaches a consistent final grouping',()=>{const h=host('alpha beta gamma delta'),all=h.chars;let changed=false;h.story.recompose=()=>{if(h.chars.some(c=>c.tracking>0)){changed=true;h.frame.lines=collection([{characters:collection(all.slice(0,6))},{characters:collection(all.slice(6,11))},{characters:collection(all.slice(11))}]);}};const p=new api.PreviewSession(h.target),result=p.preview(s({mode:'character',restart:'line',target:'both'}));assert.ok(changed);assert.ok(result.passes>=2);assert.equal(result.groups.length,3);const actual=api.makePlan(api.capture(h.story,result.data.bounds),result.settings);assert.deepEqual(plain(actual.distribution.values),plain(result.distribution.values));for(let i=0;i<result.units.length;i++)for(const at of indices([result.units[i]]))assert.equal(h.chars[at].tracking,result.distribution.values[i]);p.rollback();assert.ok(h.chars.every(c=>c.tracking===0));});
test('reapplying a grouped effect restores targets from the previous grouping',()=>{const h=host('alpha beta gamma delta');new api.PreviewSession(h.target).commit(s({mode:'character',restart:'word',target:'both',min:20,max:100}));const p=new api.PreviewSession(h.target);p.preview(s({mode:'word',restart:'never',target:'letters',max:10}));assert.equal(h.chars[4].tracking,0);assert.equal(h.chars[5].tracking,0);p.rollback();assert.ok(h.chars.some(c=>c.tracking===100));});

test('all unit/group/target combinations stay disjoint and within the chosen scope',()=>{const d=data('Alpha beta. Gamma delta!\rEpsilon zeta eta. Theta?');d.frames=[{start:0,end:24,id:8},{start:25,end:d.bounds.end-5,id:9}];d.lines=[{start:0,end:11},{start:12,end:24},{start:25,end:41},{start:42,end:d.bounds.end}];for(const mode of ['character','word','sentence','paragraph','line','frame'])for(const restart of ['never','word','sentence','paragraph','line','frame'])for(const target of ['letters','spaces','both']){let p;try{p=api.makePlan(d,s({mode,restart,target,property:'pointSize',min:10,max:30}));}catch(e){assert.match(e.message,/No matching targets/);continue;}const all=indices(p.units);assert.equal(new Set(all).size,all.length,mode+'/'+restart+'/'+target);assert.ok(all.every(i=>i>=0&&i<=d.bounds.end));assert.equal(p.units.length,p.distribution.values.length);assert.equal(p.groups.reduce((n,g)=>n+g.count,0),p.units.length);assert.ok(p.distribution.values.every(v=>Number.isFinite(v)&&v>=10&&v<=30));if(target==='spaces')assert.ok(all.every(i=>d.characters[i].kind==='space'));if(target==='letters')assert.ok(all.every(i=>d.characters[i].kind==='text'));}});
test('grouping respects absolute indices in a partial selection',()=>{const d=data('cde fghi. jkl mno');const offset=37;d.bounds.start+=offset;d.bounds.end+=offset;for(const c of d.characters)c.index+=offset;for(const key of ['words','lines'])for(const span of d[key]){span.start+=offset;span.end+=offset;}const p=api.makePlan(d,s({mode:'character',restart:'sentence',property:'pointSize',min:10,max:30}));assert.equal(p.groups.length,2);assert.ok(indices(p.units).every(i=>i>=37&&i<=d.bounds.end));assert.equal(p.groups[0].distribution.values[0],10);assert.equal(p.groups[1].distribution.values[0],10);});
test('the UI persists restart choice and group inspection never changes the document transaction',()=>{const h=uiHost();interaction=root=>{const mode=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Word'),restart=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Never');mode.selection=2;mode.onChange();restart.selection=1;restart.onChange();const labelIndex=root.controls.findIndex(c=>c.type==='statictext'&&c.text==='Group'),group=root.controls[labelIndex+1];assert.equal(group.enabled,false);const graphMode=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Average');graphMode.selection=1;graphMode.onChange();assert.equal(group.enabled,true);const transaction=h.doc.history[0],before=JSON.stringify(h.doc.state);group.text='2';group.onChanging();assert.equal(h.doc.history[0],transaction);assert.equal(JSON.stringify(h.doc.state),before);root.controls.find(c=>c.type==='button'&&c.text==='Apply').onClick();};const result=api.showDialog(h.target);assert.equal(result.settings.restart,'word');assert.equal(result.settings.mode,'character');assert.equal(h.doc.history.length,1);});
test('native smart-quote enumerators retain punctuation for sentence boundaries and targeting',()=>{ctx.SpecialCharacters.DOUBLE_LEFT_QUOTE=101;ctx.SpecialCharacters.DOUBLE_RIGHT_QUOTE=102;const h=host('"Done!" Next?'),first=h.chars[0],last=h.chars[6];first.contents=101;last.contents=102;const captured=api.capture(h.story,{start:0,end:h.chars.length-1}),p=api.makePlan(captured,s({mode:'sentence',property:'pointSize'}));assert.equal(captured.characters[0].text,'“');assert.equal(captured.characters[6].text,'”');assert.equal(p.units.length,2);assert.ok(indices(p.units).includes(0));});
test('width-only processing never clears tracking through an inactive text checkbox',()=>{const h=host('alpha beta');h.chars.forEach(c=>c.tracking=180);const p=new api.PreviewSession(h.target);p.preview(s({textEnabled:false,clearTracking:true}));assert.ok(h.chars.every(c=>c.tracking===180));p.rollback();assert.ok(h.chars.every(c=>c.tracking===180));});
test('frame scope resamples word values after text becomes overset and restores dropped targets',()=>{const h=host('alpha beta gamma'),all=h.chars;h.target.scopes=[{kind:'frame',bounds:{start:0,end:all.length-1}}];h.story.recompose=()=>{if(h.chars.some(c=>c.tracking>0))h.frame.lines=collection([{characters:collection(all.slice(0,11))}]);};const p=new api.PreviewSession(h.target),r=p.preview(s({mode:'word',restart:'never'}));assert.equal(r.units.length,2);assert.equal(r.data.bounds.end,10);assert.deepEqual(plain(r.distribution.values),[0,100]);assert.ok(h.chars.slice(11).every(c=>c.tracking===0),'Dropped text must not retain a previous pass');p.rollback();assert.ok(h.chars.every(c=>c.tracking===0));});
test('frame scope includes text newly pulled into the frame by composition',()=>{const h=host('alpha beta gamma'),all=h.chars;h.frame.lines=collection([{characters:collection(all.slice(0,11))}]);h.target.scopes=[{kind:'frame',bounds:{start:0,end:10}}];h.story.recompose=()=>{if(h.chars.some(c=>c.tracking>0))h.frame.lines=collection([{characters:collection(all)}]);};const p=new api.PreviewSession(h.target),r=p.preview(s({mode:'word',restart:'never'}));assert.equal(r.units.length,3);assert.equal(r.data.bounds.end,all.length-1);assert.deepEqual(plain(r.distribution.values),[0,50,100]);assert.equal(h.chars.at(-1).tracking,100);p.rollback();assert.ok(h.chars.every(c=>c.tracking===0));});
test('line cycles identify the moving boundary instead of keeping an approximate curve',()=>{let state=0;const base=data('abc def ghi'),layouts=[[{start:0,end:7},{start:8,end:10}],[{start:0,end:3},{start:4,end:10}]];assert.throws(()=>api.settleLines({capture(){return{...base,lines:layouts[state]};},restore(){},apply(){state=1-state;},recompose(){}},s({mode:'line',target:'both'})),/oscillates.*Line 1.*(?:1 and 2|2 and 1) words/);});
test('metrics fit the glyph gap below each source line rather than the midpoint between baselines',()=>{const lines=[{key:'a',column:0,baseline:20,top:6,bottom:24,leading:24},{key:'b',column:0,baseline:44,top:30,bottom:48,leading:24}];const positions=api.metricsRows(lines,3.6,1.4,.5);assert.ok(positions.a.baseline-3.6>=24.5-1e-9);assert.ok(positions.a.baseline+1.4<=29.5+1e-9);assert.equal(positions.a.crowded,false);assert.ok(positions.b.baseline-3.6>48);});
test('metrics flag insufficient leading and keep independent columns separate',()=>{const positions=api.metricsRows([{key:'a',column:0,baseline:20,top:6,bottom:24,leading:16},{key:'b',column:0,baseline:36,top:22,bottom:40,leading:16},{key:'c',column:1,baseline:20,top:6,bottom:24,leading:30},{key:'d',column:1,baseline:50,top:36,bottom:54,leading:30}],3.6,1.4,.5);assert.equal(positions.a.crowded,true);assert.equal(positions.c.crowded,false);assert.ok(positions.c.baseline-3.6>=24.5);assert.ok(positions.c.baseline+1.4<=35.5);});
test('line convergence checks effective tracking values rather than requiring identical line counts',()=>{let state=0,last;const base=data('abc def ghi'),layouts=[[{start:0,end:7},{start:8,end:10}],[{start:0,end:3},{start:4,end:7},{start:8,end:10}]],cfg=s({mode:'word',restart:'line',target:'letters',min:150,max:150});const baseline=Object.fromEntries(base.characters.map(c=>[c.index,0]));const p=api.settleLines({capture(){return{...base,lines:layouts[state]};},restore(){},apply(p){last=p;state=1-state;},matches(applied,desired){return api.trackingPlansEquivalent(applied,desired,baseline);},recompose(){}},cfg);assert.equal(p.passes,1);assert.equal(p.groups.length,3);assert.equal(api.trackingPlansEquivalent(last,p,baseline),true);});
test('effective-tracking convergence rejects changed values and dropped nonbaseline targets',()=>{const make=(start,end,value)=>({units:[{spans:[{start,end}]}],distribution:{values:[value]}});assert.equal(api.trackingPlansEquivalent(make(0,2,150),make(0,1,150),{0:0,1:0,2:0}),false);assert.equal(api.trackingPlansEquivalent(make(0,2,150),make(0,2,100),{0:0,1:0,2:0}),false);assert.equal(api.trackingPlansEquivalent(make(0,2,0),make(0,1,0),{0:0,1:0,2:0}),true);});
test('clear tracking follows incoming frame text and preserves the original overset baseline',()=>{const h=host('alpha beta gamma delta epsilon'),all=h.chars;h.chars.forEach(c=>c.tracking=180);h.frame.lines=collection([{characters:collection(all.slice(0,11))}]);h.target.scopes=[{kind:'frame',bounds:{start:0,end:10}}];h.story.recompose=()=>{if(h.chars[0].tracking===0)h.frame.lines=collection([{characters:collection(all.slice(0,17))}]);};const p=new api.PreviewSession(h.target),r=p.preview(s({clearTracking:true,max:100}));assert.equal(r.data.bounds.end,16);assert.equal(h.chars[15].tracking,0);assert.equal(h.chars[16].tracking,0);assert.ok(h.chars.slice(17).every(c=>c.tracking===180));p.rollback();assert.ok(h.chars.every(c=>c.tracking===180));});
test('clear tracking restores the original baseline when previously visible text becomes overset',()=>{const h=host('alpha beta gamma'),all=h.chars;h.chars.forEach(c=>c.tracking=180);h.target.scopes=[{kind:'frame',bounds:{start:0,end:all.length-1}}];h.story.recompose=()=>{h.frame.lines=collection([{characters:collection(h.chars[6].tracking>180?all.slice(0,11):all)}]);};const p=new api.PreviewSession(h.target),r=p.preview(s({clearTracking:true,min:200,max:500}));assert.equal(r.data.bounds.end,10);assert.ok(h.chars.slice(11).every(c=>c.tracking===180));p.rollback();assert.ok(h.chars.every(c=>c.tracking===180));});
test('committed frame clearing saves zero for incoming gaps on later replacement runs',()=>{const h=host('alpha beta gamma delta epsilon'),all=h.chars;h.chars.forEach(c=>c.tracking=180);h.frame.lines=collection([{characters:collection(all.slice(0,11))}]);h.target.scopes=[{kind:'frame',bounds:{start:0,end:10}}];h.story.recompose=()=>{if(h.chars[0].tracking===0)h.frame.lines=collection([{characters:collection(all.slice(0,17))}]);};new api.PreviewSession(h.target).commit(s({clearTracking:true,max:100}));new api.PreviewSession(h.target).commit(s({clearTracking:false,max:20}));assert.equal(h.chars[15].tracking,0);assert.equal(h.chars[16].tracking,0);assert.ok(h.chars.slice(17).every(c=>c.tracking===180));h.doc.undo();h.doc.undo();assert.ok(h.chars.every(c=>c.tracking===180));});
test('managed line-break insertion and removal preserve sparse formatting histories',()=>{const rows=[{start:0,end:4,values:{tracking:10}},{start:5,end:9,values:{tracking:40}}],offsets=[2,5,8],positions=[2,6,10];const inserted=plain(api.remapSnapshot(rows,offsets,false));const removed=plain(api.remapSnapshot(inserted,positions,true));function expand(rows){const v={};for(const row of rows)for(let i=row.start;i<=row.end;i++)v[i]=row.values.tracking;return v;}assert.deepEqual(expand(removed),expand(rows));assert.ok(positions.every(p=>!Object.hasOwn(expand(inserted),p)));assert.deepEqual(plain(api.remapBounds({start:3,end:8},offsets,false)),{start:4,end:11});assert.deepEqual(plain(api.remapBounds({start:4,end:11},positions,true)),{start:3,end:8});});
test('line-break removal excludes owned break characters from saved values',()=>{const rows=[{start:0,end:7,values:{tracking:0}}],r=plain(api.remapSnapshot(rows,[0,3,7],true));const all=[];for(const row of r)for(let i=row.start;i<=row.end;i++)all.push(i);assert.deepEqual(all,[0,1,2,3,4]);});
test('width-only processing preserves existing fixed line breaks and their ownership',()=>{const h=host('alpha\nbeta'),key='TrackingRamp.v5.lineBreaks',meta=JSON.stringify({version:1,property:'tracking',signature:api.signature(h.story),positions:[5]});h.story.insertLabel(key,meta);const p=new api.PreviewSession(h.target);p.preview(s({textEnabled:false}));assert.equal(h.story.contents,'alpha\nbeta');assert.equal(h.story.extractLabel(key),meta);p.rollback();assert.equal(h.story.extractLabel(key),meta);});

test('underline properties enable targets and preserve automatic values and flags on Cancel',()=>{for(const property of ['underlineWeight','underlineOffset']){const h=host('alpha beta gamma'),before=JSON.stringify(h.doc.state),p=new api.PreviewSession(h.target),r=p.preview(s({property,min:.25,max:4}));assert.equal(h.chars[0][property],.25);assert.equal(h.chars.at(-1)[property],4);assert.ok(h.chars[0].underline);assert.equal(h.chars[5].underline,false);p.rollback();assert.equal(JSON.stringify(h.doc.state),before);}});
test('reapplication restores underline activation and automatic defaults outside the new targets',()=>{const h=host('alpha beta gamma');new api.PreviewSession(h.target).commit(s({property:'underlineWeight',target:'both',min:.5,max:3}));new api.PreviewSession(h.target).commit(s({property:'underlineWeight',target:'letters',min:.25,max:1}));assert.equal(h.chars[5].underline,false);assert.equal(h.chars[5].underlineWeight,-9999);assert.equal(h.chars[0].underline,true);assert.equal(h.chars.at(-1).underlineWeight,1);});
test('replacing underline weight keeps activation owned by an offset effect',()=>{const h=host('alpha beta gamma');new api.PreviewSession(h.target).commit(s({property:'underlineWeight',target:'both',min:.5,max:3}));new api.PreviewSession(h.target).commit(s({property:'underlineOffset',target:'both',min:1,max:5}));new api.PreviewSession(h.target).commit(s({property:'underlineWeight',target:'letters',min:.25,max:1}));assert.equal(h.chars[5].underline,true);assert.ok(h.chars[5].underlineOffset>0);});
test('paragraph indents are atomic even when a requested restart crosses a paragraph',()=>{const d=data('one two\rthree four\rfive six'),r=api.makePlan(d,s({property:'leftIndent',mode:'character',restart:'word',target:'spaces',min:0,max:24}));assert.equal(r.units.length,3);assert.equal(r.settings.mode,'paragraph');assert.equal(r.settings.restart,'never');assert.equal(r.settings.target,'both');assert.deepEqual(Array.from(r.distribution.values),[0,12,24]);assert.deepEqual(plain(r.units[0].spans),[{start:0,end:7}]);});
test('indent selection affects complete intersecting paragraphs and restores those paragraphs on reapply',()=>{for(const property of ['leftIndent','rightIndent','firstLineIndent']){const h=host('outside\rfirst selected paragraph\rsecond selected paragraph\runtouched');h.target.scopes=[{kind:'selection',bounds:{start:11,end:38}}];const before=JSON.stringify(h.doc.state),p=new api.PreviewSession(h.target),r=p.preview(s({property,min:6,max:24}));assert.equal(r.units.length,2);assert.ok(h.chars.slice(8,33).every(c=>c[property]===6));assert.ok(h.chars.slice(33,59).every(c=>c[property]===24));assert.equal(h.chars[0][property],0);assert.equal(h.chars.at(-1)[property],0);p.rollback();assert.equal(JSON.stringify(h.doc.state),before);new api.PreviewSession(h.target).commit(s({property,min:6,max:24}));h.target.scopes=[{kind:'selection',bounds:{start:11,end:14}}];new api.PreviewSession(h.target).commit(s({property,min:3,max:3}));assert.equal(h.chars[8][property],3);assert.equal(h.chars[33][property],0);h.doc.undo();h.doc.undo();assert.equal(JSON.stringify(h.doc.state),before);}});
test('identical normalized indent previews reuse the same transaction',()=>{const h=host('one\rtwo\rthree'),p=new api.PreviewSession(h.target),cfg=s({property:'leftIndent',min:0,max:20}),first=p.preview(cfg),transaction=h.doc.history[0];assert.equal(p.preview(cfg),first);p.commit(cfg);assert.equal(h.doc.history[0],transaction);assert.equal(h.doc.history.length,1);});
test('indent UI locks paragraph controls and restores the prior structure on another property',()=>{const h=uiHost();interaction=root=>{const property=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Tracking'),mode=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Word'),restart=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Never');mode.selection=2;mode.onChange();property.selection=15;property.onChange();assert.equal(mode.selection.index,4);assert.equal(restart.selection.index,0);assert.equal(mode.enabled,false);assert.equal(restart.enabled,false);property.selection=13;property.onChange();assert.equal(mode.selection.index,2);assert.equal(mode.enabled,true);root.controls.find(c=>c.type==='button'&&c.text==='Cancel').onClick();};api.showDialog(h.target);});
test('new properties expose point units, fractional steps, and safe signed indent limits',()=>{for(const id of ['underlineWeight','underlineOffset','leftIndent','rightIndent','firstLineIndent'])assert.equal(api.propertyInfo(id).unit,'pt');assert.equal(api.propertyInfo('leftIndent').low,0);assert.equal(api.propertyInfo('rightIndent').low,0);assert.ok(api.propertyInfo('firstLineIndent').low<0);assert.deepEqual(Array.from(api.buildDistribution(3,s({property:'underlineWeight',min:.25,max:.75})).values),[.25,.5,.75]);});
test('native plural paragraph specifiers are resolved before storing scalar story indices',()=>{const h=host('outside\rselected one\rselected two'),originalRange=h.story.characters.itemByRange;h.story.characters.itemByRange=(a,b)=>{const r=originalRange(a,b),real=r.paragraphs;r.paragraphs={...real,item(i){const p=real.item(i);return{characters:{length:p.characters.length,firstItem:()=>({index:[p.characters.firstItem().index]}),lastItem:()=>({index:[p.characters.lastItem().index]})}};}};return r;};h.target.scopes=[{kind:'selection',bounds:{start:10,end:25}}];const p=new api.PreviewSession(h.target),r=p.preview(s({property:'leftIndent',min:0,max:12}));assert.ok(r.units.every(u=>u.spans.every(span=>typeof span.start==='number'&&typeof span.end==='number')));p.rollback();});

test('automatic stabilization keeps a cycling line curve without reducing requested values',()=>{const h=host('abc def ghi'),all=h.chars,A=[{characters:collection(all.slice(0,8))},{characters:collection(all.slice(8))}],B=[{characters:collection(all.slice(0,4))},{characters:collection(all.slice(4))}];h.frame.lines=collection(A);h.story.recompose=()=>{h.frame.lines=collection(h.chars[4].tracking===0?B:A);};const p=new api.PreviewSession(h.target),r=p.preview(s({mode:'line',target:'both',max:100,autoStabilize:true,lockLines:false}));assert.equal(r.fixedSampling,true);assert.deepEqual(Array.from(r.distribution.values),[0,100]);p.rollback();assert.ok(h.chars.every(c=>c.tracking===0));});
test('automatic frame stabilization restores outgoing text without restarting the sampling cycle',()=>{const h=host('abc def ghi'),all=h.chars;h.target.scopes=[{kind:'frame',bounds:{start:0,end:10}}];h.story.recompose=()=>{h.frame.lines=collection([{characters:collection(h.chars[8].tracking>0?all.slice(0,8):all)}]);};const p=new api.PreviewSession(h.target),r=p.preview(s({target:'both',autoStabilize:true,lockLines:false}));assert.equal(r.fixedSampling,true);assert.ok(r.units.flatMap(u=>u.spans).every(span=>span.end<=r.data.bounds.end));assert.equal(h.chars[8].tracking,0);p.rollback();assert.ok(h.chars.every(c=>c.tracking===0));});
test('kept properties survive draft changes and Cancel restores the whole stack',()=>{const h=host('alpha beta gamma'),before=JSON.stringify(h.doc.state),p=new api.PreviewSession(h.target),skew=s({property:'skew',min:-10,max:20});p.preview(skew);p.keep(skew);const values=h.chars.map(c=>c.skew);p.preview(s({max:200}));p.preview(s({max:40}));assert.deepEqual(h.chars.map(c=>c.skew),values);assert.ok(h.chars.some(c=>c.tracking>0));p.rollback();assert.equal(JSON.stringify(h.doc.state),before);});
test('committing stacked properties creates one Undo group and blocks duplicate properties',()=>{const h=host('alpha beta gamma'),p=new api.PreviewSession(h.target),skew=s({property:'skew',min:-10,max:20});p.keep(skew);assert.throws(()=>p.preview(skew),/already|kept/i);p.commit(s({max:100}));assert.equal(h.doc.history.length,1);assert.ok(h.chars.some(c=>c.skew!==0));h.doc.undo();assert.ok(h.chars.every(c=>c.skew===0&&c.tracking===0));});

test('Undo addition returns the kept settings and restores them as the editable stage',()=>{const h=host('alpha beta gamma'),p=new api.PreviewSession(h.target),skew=s({property:'skew',min:-12,max:18,curve:'sine'});p.keep(skew);p.preview(s({max:100}));const saved=p.undoAddition();assert.equal(saved.property,'skew');assert.equal(saved.curve,'sine');assert.equal(p.stages.length,0);p.preview(saved);assert.ok(h.chars.every(c=>c.tracking===0));assert.ok(h.chars.some(c=>c.skew!==0));p.rollback();});
test('kept-only preview preserves baked effects when the active preview is off',()=>{const h=host('alpha beta gamma'),p=new api.PreviewSession(h.target),skew=s({property:'skew',min:-12,max:18});p.keep(skew);p.preview(s({max:100}));p.preview(null);assert.ok(h.chars.some(c=>c.skew!==0));assert.ok(h.chars.every(c=>c.tracking===0));assert.equal(h.doc.history.length,1);p.rollback();assert.ok(h.chars.every(c=>c.skew===0));});
test('three-property stack replays frozen values and commits as one Undo action',()=>{const h=host('alpha beta gamma'),p=new api.PreviewSession(h.target);p.keep(s({property:'skew',min:-10,max:20}));const skew=h.chars.map(c=>c.skew);p.keep(s({max:100}));const tracking=h.chars.map(c=>c.tracking);p.commit(s({property:'baselineShift',min:0,max:5}));assert.deepEqual(h.chars.map(c=>c.skew),skew);assert.deepEqual(h.chars.map(c=>c.tracking),tracking);assert.equal(h.doc.history.length,1);h.doc.undo();assert.ok(h.chars.every(c=>c.skew===0&&c.tracking===0&&c.baselineShift===0));});
test('a failed draft can return to the last kept effect without leaving draft formatting',()=>{const h=host('alpha beta gamma'),p=new api.PreviewSession(h.target);p.keep(s({property:'skew',min:-10,max:20}));assert.throws(()=>p.preview(s({property:'designAxes',axisName:'Missing',min:100,max:900})));p.preview(null);assert.ok(h.chars.some(c=>c.skew!==0));assert.ok(h.chars.every(c=>c.tracking===0));p.rollback();});
test('strict composition mode still rejects a cycle and restores the complete baseline',()=>{const h=host('abc def ghi'),all=h.chars,A=[{characters:collection(all.slice(0,8))},{characters:collection(all.slice(8))}],B=[{characters:collection(all.slice(0,4))},{characters:collection(all.slice(4))}];h.frame.lines=collection(A);h.story.recompose=()=>{h.frame.lines=collection(h.chars[4].tracking===0?B:A);};const before=JSON.stringify(h.doc.state),p=new api.PreviewSession(h.target);assert.throws(()=>p.preview(s({mode:'line',target:'both',autoStabilize:false,lockLines:false})),/oscillates/);assert.equal(JSON.stringify(h.doc.state),before);});
test('Add property UI keeps skew, offers only unused properties, and commits the stack',()=>{const OriginalWindow=ctx.Window;ctx.Window=function(type,title){const w=new OriginalWindow(type,title);if(title==='Add property')w.show=function(){const list=w.controls.find(c=>c.type==='dropdownlist');assert.ok(!list.items.includes('Skew'));list.selection=0;w.controls.find(c=>c.type==='button'&&c.text==='Add').onClick();return w.result;};return w;};try{const h=uiHost();interaction=root=>{const property=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Tracking');property.selection=7;const skew=h.chars.map(c=>c.skew);root.controls.find(c=>c.type==='button'&&c.text==='+ Add property').onClick();assert.equal(property.selection.index,0);assert.deepEqual(h.chars.map(c=>c.skew),skew);assert.ok(root.controls.some(c=>typeof c.text==='string'&&c.text==='Kept: Skew'));assert.ok(h.chars.some(c=>c.tracking>0));root.controls.find(c=>c.type==='button'&&c.text==='Undo addition').onClick();assert.equal(property.selection.index,7);assert.ok(!root.controls.some(c=>c.type==='dropdownlist'&&c.items?.[0]==='Letters'));root.controls.find(c=>c.type==='button'&&c.text==='+ Add property').onClick();root.controls.find(c=>c.type==='button'&&c.text==='Apply all').onClick();};api.showDialog(h.target);assert.equal(h.doc.history.length,1);h.doc.undo();assert.ok(h.chars.every(c=>c.skew===0&&c.tracking===0));}finally{ctx.Window=OriginalWindow;}});
test('fixed sampling with Clear tracking restores the original overset baseline after frame trimming',()=>{const h=host('abc def ghi jkl'),all=h.chars;h.chars.forEach(c=>c.tracking=180);h.target.scopes=[{kind:'frame',bounds:{start:0,end:all.length-1}}];h.story.recompose=()=>{const end=h.chars[0].tracking>180?11:all.length;h.frame.lines=collection(h.chars[4].tracking===200?[{characters:collection(all.slice(0,4))},{characters:collection(all.slice(4,end))}]:[{characters:collection(all.slice(0,8))},{characters:collection(all.slice(8,end))}]);};const p=new api.PreviewSession(h.target),r=p.preview(s({mode:'line',target:'both',min:200,max:500,clearTracking:true,autoStabilize:true,lockLines:false}));assert.equal(r.fixedSampling,true);assert.ok(h.chars.slice(r.data.bounds.end+1).every(c=>c.tracking===180));p.rollback();assert.ok(h.chars.every(c=>c.tracking===180));});
test('typing a partial numeric value does not immediately recalculate the document',()=>{const h=uiHost();interaction=root=>{const transaction=h.doc.history[0],max=root.controls.filter(c=>c.type==='edittext')[2];max.text='2';max.onChanging();assert.equal(h.doc.history[0],transaction,'Wait for typing to pause before changing the preview');root.controls.find(c=>c.type==='button'&&c.text==='Cancel').onClick();};api.showDialog(h.target);});

test('typing bursts coalesce into one preview 350 ms after the final keystroke',()=>{let now=0,value='2',calls=[],second=false,third=false,delay;delay=new api.PreviewDelay(350,()=>calls.push({value,at:now}),{now:()=>now,wait:ms=>now+=ms,pump(){if(now>=72&&!second){second=true;value='20';delay.request();}if(now>=168&&!third){third=true;value='200';delay.request();}},alive:()=>true});delay.request();assert.equal(calls.length,1);assert.equal(calls[0].value,'200');assert.ok(calls[0].at>=518&&calls[0].at<=530);assert.equal(delay.pending,false);});
test('Cancel during a typing delay prevents all late preview callbacks',()=>{let now=0,calls=0,delay;delay=new api.PreviewDelay(350,()=>calls++,{now:()=>now,wait:ms=>now+=ms,pump(){if(now>=96)delay.dispose();},alive:()=>true});delay.request();assert.equal(calls,0);assert.equal(delay.waiting,false);delay.request();assert.equal(calls,0);});
test('committing a field flushes the latest value immediately and only once',()=>{let now=0,calls=0,delay;delay=new api.PreviewDelay(350,()=>calls++,{now:()=>now,wait:ms=>now+=ms,pump(){if(now>=96)delay.flush();},alive:()=>true});delay.request();assert.equal(calls,1);assert.ok(now<350);delay.flush();assert.equal(calls,1);});
test('Apply uses a pending numeric value and Cancel discards it',()=>{const h=uiHost();interaction=root=>{const max=root.controls.filter(c=>c.type==='edittext')[2];max.text='275';max.onChanging();root.controls.find(c=>c.type==='button'&&c.text==='Apply').onClick();};api.showDialog(h.target);assert.equal(Math.max(...h.chars.map(c=>c.tracking)),275);h.doc.undo();interaction=root=>{const max=root.controls.filter(c=>c.type==='edittext')[2];max.text='275';max.onChanging();root.controls.find(c=>c.type==='button'&&c.text==='Cancel').onClick();};api.showDialog(h.target);assert.ok(h.chars.every(c=>c.tracking===0));});
test('native bulk bounds preserve scalar indices and fall back on unresolved columns',()=>{const good=vm.runInContext('({length:2,everyItem:function(){return{characters:{firstItem:function(){return{index:[0,5]}},lastItem:function(){return{index:[3,9]}}}}}})',ctx);assert.deepEqual(plain(api.collectionBounds(good)),[{start:0,end:3},{start:5,end:9}]);const all=[{characters:collection([{index:2},{index:6}])},{characters:collection([{index:9},{index:12}])}],bad={...collection(all),everyItem:()=>({characters:{firstItem:()=>({index:[2]}),lastItem:()=>({index:[12]})}})};assert.deepEqual(plain(api.collectionBounds(bad)),[{start:2,end:6},{start:9,end:12}]);});
test('numeric snapshots avoid resolving every character when complete bulk columns exist',()=>{const cols=vm.runInContext('[0,0,25]',ctx),story={characters:{length:3,everyItem:()=>({tracking:cols,getElements(){throw Error('Unnecessary scalar character resolution');}})}};assert.deepEqual(plain(api.takeSnapshot(story,['tracking'])),[{start:0,end:1,values:{tracking:0}},{start:2,end:2,values:{tracking:25}}]);});
test('numeric kept patches preserve previous-effect removal outside a narrower scope',()=>{const h=host('alpha beta gamma');new api.PreviewSession(h.target).commit(s({property:'skew',target:'both',min:10,max:30}));const before=h.chars.map(c=>c.skew);h.target.scopes=[{kind:'selection',bounds:{start:0,end:4}}];const p=new api.PreviewSession(h.target),cfg=s({property:'skew',min:5,max:5});p.keep(cfg);assert.ok(p.stages[0].patch);p.preview(s({max:40}));assert.ok(h.chars.slice(5).every(c=>c.skew===0));assert.ok(h.chars.slice(0,5).every(c=>c.skew===5));p.rollback();assert.deepEqual(h.chars.map(c=>c.skew),before);});
test('advanced kept effects retain the complete replay path',()=>{const h=host('alpha beta gamma'),p=new api.PreviewSession(h.target);p.keep(s({property:'designAxes',axisName:'Weight',min:100,max:900}));assert.equal(p.stages[0].patch,null);const axes=h.chars.map(c=>c.designAxes[0]);p.preview(s({max:80}));assert.deepEqual(h.chars.map(c=>c.designAxes[0]),axes);p.rollback();});
test('a changed replay signature falls back to full reconstruction of the kept effect',()=>{const h=host('alpha beta gamma'),p=new api.PreviewSession(h.target);p.keep(s({property:'skew',min:-10,max:20}));const before=h.chars.map(c=>c.skew);p.stages[0].replay.signature='stale';p.preview(s({max:40}));assert.deepEqual(h.chars.map(c=>c.skew),before);p.rollback();});
test('slider movement updates its field and graph without recalculating until release',()=>{const h=uiHost();interaction=root=>{const curve=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Linear'),slider=root.controls.find(c=>c.type==='slider'),graph=root.controls.find(c=>c.type==='panel'&&Array.isArray(c.preferredSize)&&c.preferredSize[1]===165);curve.selection=1;curve.onChange();const transaction=h.doc.history[0],before=JSON.stringify(h.doc.state),writes=graph.resizeWrites;for(const value of [3,4,6]){slider.value=value;slider.onChanging();assert.equal(h.doc.history[0],transaction,'No native preview during slider movement');assert.equal(JSON.stringify(h.doc.state),before);}assert.ok(graph.resizeWrites>writes,'Graph still repaints while dragging');assert.ok(root.controls.some(c=>c.type==='edittext'&&c.text==='6'));slider.onChange();assert.notEqual(h.doc.history[0],transaction);assert.notEqual(JSON.stringify(h.doc.state),before);root.controls.find(c=>c.type==='button'&&c.text==='Apply').onClick();};const result=api.showDialog(h.target);assert.equal(result.settings.power,6);assert.equal(h.doc.history.length,1);h.doc.undo();assert.ok(h.chars.every(c=>c.tracking===0));});
test('Cancel after slider movement preserves the original document',()=>{const h=uiHost(),before=JSON.stringify(h.doc.state);interaction=root=>{const curve=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Linear');curve.selection=4;curve.onChange();const transaction=h.doc.history[0],slider=root.controls.find(c=>c.type==='slider');slider.value=37.2;slider.onChanging();assert.equal(h.doc.history[0],transaction);root.controls.find(c=>c.type==='button'&&c.text==='Cancel').onClick();};assert.equal(api.showDialog(h.target),null);assert.equal(JSON.stringify(h.doc.state),before);});
test('line length exposes percent widths and forces whole resulting lines',()=>{const info=api.propertyInfo('lineLength');assert.equal(info.unit,'% frame width');assert.equal(info.max,100);const cfg=api.effectiveSettings(s({property:'lineLength',mode:'word',restart:'sentence',target:'spaces'}));assert.equal(cfg.mode,'line');assert.equal(cfg.restart,'never');assert.equal(cfg.target,'both');assert.deepEqual(plain(api.centeredLineInsets(400,60)),{leftIndent:80,rightIndent:80});assert.throws(()=>api.centeredLineInsets(400,101),/Line length/);});
test('line length refits rows against the new count and applies the complete curve',()=>{let resets=0,index=0;const cfg=s({property:'lineLength',min:40,max:100});const result=api.layoutLineLengths({reset(){resets++;index=0;},next(value){if(index===4)return null;return{spans:[{start:index,end:index++}],percent:value};}},cfg,2);assert.equal(resets,2);assert.equal(result.fixedSampling,false);assert.deepEqual(plain(result.values),[40,60,80,100]);assert.equal(result.rows.length,4);});
test('line length count cycles finish with explicit fixed sampling and unchanged widths',()=>{let cursor=0,total=0;const result=api.layoutLineLengths({reset(){cursor=0;total=total===3?4:3;},next(value){return cursor++<total?{percent:value}:null;}},s({property:'lineLength',min:50,max:90}),4);assert.equal(result.fixedSampling,true);assert.ok(result.values.every(v=>v>=50&&v<=90));assert.ok(result.passes<=3);});
test('line length UI selects frame and line structure and restores prior controls on exit',()=>{const h=uiHost();h.target.scopes.push({kind:'frame',bounds:{start:0,end:h.chars.length-1}});interaction=root=>{const live=root.controls.find(c=>c.type==='checkbox'&&c.text==='Preview');live.value=false;live.onClick();const property=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Tracking'),mode=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Word'),restart=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Never');const scopeControl=root.controls[root.controls.findIndex(c=>c.type==='statictext'&&c.text==='Scope')+1];property.selection=18;property.onChange();assert.equal(scopeControl.selection.index,1);assert.equal(scopeControl.enabled,false);assert.equal(mode.selection.index,1);assert.equal(restart.selection.index,0);assert.equal(mode.enabled,false);assert.equal(restart.enabled,false);assert.ok(root.controls.some(c=>c.type==='statictext'&&c.text==='% frame width'));property.selection=0;property.onChange();assert.equal(scopeControl.selection.index,0);assert.equal(scopeControl.enabled,true);assert.equal(mode.selection.index,0);assert.equal(mode.enabled,true);root.controls.find(c=>c.type==='button'&&c.text==='Cancel').onClick();};api.showDialog(h.target);});
test('strict line length rejects a cycling row count',()=>{let n=0,cursor=0;assert.throws(()=>api.layoutLineLengths({reset(){n=n===3?4:3;cursor=0;},next(percent){return cursor++<n?{percent}:null;}},s({property:'lineLength',min:40,max:100,autoStabilize:false}),4),/oscillates/);});
function lengthBreakStory(){const chars=Array.from('a\rb\nc',contents=>({contents})),labels={};return{characters:{length:chars.length,item:i=>chars[i]},get contents(){return chars.map(c=>c.contents).join('');},recompose(){},extractLabel:k=>labels[k]||'',insertLabel(k,v){labels[k]=v;}};}
test('restoring managed paragraph breaks preserves indices and retags other histories',()=>{const story=lengthBreakStory(),before=api.signature(story),history={effects:{lineLength:{signature:before,breaks:[{index:1,contents:' '}]},tracking:{signature:before}}};story.insertLabel('TrackingRamp.v5.lineBreaks',JSON.stringify({signature:before,positions:[3],version:1,property:'tracking'}));api.restoreLengthBreaks(story,history,s({property:'lineLength'}));assert.equal(story.contents,'a b\nc');assert.equal(story.characters.length,5);assert.equal(history.effects.tracking.signature,api.signature(story));const locks=plain(api.decode(story.extractLabel('TrackingRamp.v5.lineBreaks')));assert.equal(locks.signature,api.signature(story));assert.deepEqual(locks.positions,[3]);});
test('malformed owned paragraph records are rejected before changing any text',()=>{for(const breaks of [[{index:1,contents:'changed text'}],[{index:2,contents:' '}],[{index:1,contents:' '},{index:1,contents:' '}]]){const story=lengthBreakStory(),before=story.contents;assert.throws(()=>api.restoreLengthBreaks(story,{effects:{lineLength:{signature:api.signature(story),breaks}}},s({property:'lineLength'})),/no longer match/);assert.equal(story.contents,before);}});
test('tracking soft-break remapping preserves owned paragraph positions and baselines',()=>{const history={effects:{lineLength:{signature:'before',original:[{start:0,end:9,values:{leftIndent:4}}],breaks:[{index:4,contents:' '},{index:8,contents:' '}]}}};api.remapHistory(history,[2,7],false,'before','inserted');assert.deepEqual(history.effects.lineLength.breaks.map(b=>b.index),[5,10]);api.remapHistory(history,[2,8],true,'inserted','restored');assert.deepEqual(history.effects.lineLength.breaks.map(b=>b.index),[4,8]);assert.equal(history.effects.lineLength.signature,'restored');const restored=history.effects.lineLength.original.flatMap(row=>Array.from({length:row.end-row.start+1},(_,i)=>[row.start+i,row.values.leftIndent]));assert.deepEqual(plain(restored),Array.from({length:10},(_,i)=>[i,4]));});
test('v6 UI exposes added breaks separately and defaults them off',()=>{const h=uiHost();interaction=root=>{const toggle=root.controls.find(c=>c.type==='checkbox'&&c.text==='Allow added line breaks');assert.ok(toggle);assert.equal(toggle.value,false);root.controls.find(c=>c.type==='button'&&c.text==='Apply').onClick();};const r=api.showDialog(h.target);assert.equal(r.settings.allowLineBreaks,false);assert.equal(r.settings.autoStabilize,true);});
test('explicit no-break policy overrides the legacy tracking fallback flag',()=>{const h=host('abc def ghi'),all=h.chars,A=[{characters:collection(all.slice(0,8))},{characters:collection(all.slice(8))}],B=[{characters:collection(all.slice(0,4))},{characters:collection(all.slice(4))}];h.frame.lines=collection(A);h.story.recompose=()=>{h.frame.lines=collection(h.chars[4].tracking===0?B:A);};const p=new api.PreviewSession(h.target),r=p.preview(s({mode:'line',target:'both',max:100,autoStabilize:true,lockLines:true,allowLineBreaks:false}));assert.equal(r.fixedSampling,true);assert.equal(h.story.contents,'abc def ghi');p.rollback();});
test('break policies preserve explicit v5 settings while new settings require opt-in',()=>{assert.equal(api.allowsLineBreaks({}),false);assert.equal(api.allowsLineBreaks({autoStabilize:true}),false);assert.equal(api.allowsLineBreaks({lockLines:true}),true);assert.equal(api.allowsLineBreaks({lockLines:true,allowLineBreaks:false}),false);assert.equal(api.allowsLineBreaks({allowLineBreaks:true}),true);});
test('style blending is a percent-based property',()=>{const info=api.propertyInfo('styleBlend');assert.equal(info.unit,'blend %');assert.equal(info.min,0);assert.equal(info.max,100);});
function blendStyles(h,a={},b={}){const first={id:101,name:'A',isValid:true,...a},second={id:102,name:'B',isValid:true,...b};h.doc.allCharacterStyles=[first,second];return s({property:'styleBlend',styleA:101,styleB:102,mode:'word',min:0,max:100,target:'both'});}
test('style blend applies size tracking and baseline together and Cancel restores all',()=>{const h=host('alpha beta gamma'),cfg=blendStyles(h,{pointSize:14,tracking:0,baselineShift:0},{pointSize:36,tracking:200,baselineShift:12}),before=JSON.stringify(h.doc.state),p=new api.PreviewSession(h.target);const r=p.preview(cfg);assert.equal(h.chars[0].pointSize,14);assert.equal(h.chars[6].pointSize,25);assert.equal(h.chars[6].tracking,100);assert.equal(h.chars[6].baselineShift,6);assert.equal(h.chars.at(-1).pointSize,36);assert.equal(r.settings.blendDefinition.attributes.length,3);p.rollback();assert.equal(JSON.stringify(h.doc.state),before);});
test('style blend resolves based-on settings while leaving unspecified attributes unchanged',()=>{const h=host('alpha beta'),parent={id:100,name:'Parent',pointSize:18,tracking:20},cfg=blendStyles(h,{basedOn:parent,baselineShift:0},{basedOn:parent,baselineShift:10});h.doc.allCharacterStyles.push(parent);const p=new api.PreviewSession(h.target);p.preview(cfg);assert.ok(h.chars.every(c=>c.pointSize===18&&c.tracking===20));assert.ok(h.chars.every(c=>c.horizontalScale===100));p.rollback();});
test('blend attribute exclusions preserve baseline values',()=>{const h=host('alpha beta'),cfg=blendStyles(h,{pointSize:14,tracking:0},{pointSize:36,tracking:200});cfg.styleAttributes=['tracking'];const p=new api.PreviewSession(h.target);const r=p.preview(cfg);assert.ok(h.chars.every(c=>c.pointSize===24));assert.equal(h.chars.at(-1).tracking,200);assert.deepEqual(plain(r.settings.blendDefinition.excluded),['Font size']);p.rollback();});
test('one-sided and automatic style values are ignored instead of coerced into numbers',()=>{const h=host('alpha beta'),cfg=blendStyles(h,{pointSize:14,tracking:0,underlineWeight:-9999,fillTint:-1,leading:{automatic:true}},{tracking:100,underlineWeight:4,fillTint:80,leading:24});const def=api.compileStyleBlend(h.doc,cfg);assert.deepEqual(plain(def.attributes.map(a=>a.id)),['tracking']);assert.equal(def.ignored.length,4);});
test('styles without shared supported attributes fail without document changes',()=>{const h=host('alpha beta'),cfg=blendStyles(h,{fontStyle:'Italic'},{fontStyle:'Bold'}),before=JSON.stringify(h.doc.state),p=new api.PreviewSession(h.target);assert.throws(()=>p.preview(cfg),/no shared supported/);assert.equal(JSON.stringify(h.doc.state),before);cfg.styleAttributes=[];h.doc.allCharacterStyles[0].pointSize=14;h.doc.allCharacterStyles[1].pointSize=36;assert.throws(()=>p.preview(cfg),/at least one/);});
test('narrow style-blend replacement restores all previously controlled attributes',()=>{const h=host('alpha beta gamma'),cfg=blendStyles(h,{pointSize:14,tracking:0,baselineShift:0},{pointSize:36,tracking:200,baselineShift:12});new api.PreviewSession(h.target).commit(cfg);h.target.scopes=[{kind:'selection',bounds:{start:0,end:4}}];const p=new api.PreviewSession(h.target);p.preview({...cfg,styleAttributes:['pointSize'],min:100,max:100});assert.ok(h.chars.slice(5).every(c=>c.pointSize===24&&c.tracking===0&&c.baselineShift===0));assert.ok(h.chars.slice(0,5).every(c=>c.pointSize===36&&c.tracking===0&&c.baselineShift===0));p.rollback();});
test('style blend respects outgoing tracking gaps while other attributes cover full letters',()=>{const h=host('alpha beta'),cfg=blendStyles(h,{pointSize:14,tracking:80},{pointSize:36,tracking:200});cfg.target='letters';const p=new api.PreviewSession(h.target);p.preview(cfg);assert.equal(h.chars[4].pointSize,14);assert.equal(h.chars[4].tracking,0);assert.equal(h.chars[5].tracking,0);assert.equal(h.chars.at(-1).tracking,200);p.rollback();});
test('style-blend history does not claim tracking on excluded outgoing glyphs',()=>{const h=host('alpha beta'),cfg=blendStyles(h,{pointSize:14,tracking:80},{pointSize:36,tracking:200});cfg.target='letters';new api.PreviewSession(h.target).commit(cfg);const history=JSON.parse(h.doc.state.labels['TrackingRamp.v3.history']);const outgoing=history.effects.styleBlend.original.find(r=>r.start<=4&&r.end>=4);assert.ok(outgoing);assert.equal(outgoing.values.tracking,undefined);h.chars[4].tracking=333;new api.PreviewSession(h.target).commit({...cfg,styleAttributes:['pointSize']});assert.equal(h.chars[4].tracking,333);});
test('kept style blend stays frozen while another property changes and one Undo removes all',()=>{const h=host('alpha beta gamma'),cfg=blendStyles(h,{pointSize:14,tracking:0},{pointSize:36,tracking:200}),p=new api.PreviewSession(h.target);p.keep(cfg);const size=h.chars.map(c=>c.pointSize),tracking=h.chars.map(c=>c.tracking);p.commit(s({property:'skew',min:-15,max:15}));assert.deepEqual(h.chars.map(c=>c.pointSize),size);assert.deepEqual(h.chars.map(c=>c.tracking),tracking);assert.equal(h.doc.history.length,1);h.doc.undo();assert.ok(h.chars.every(c=>c.pointSize===24&&c.tracking===0&&c.skew===0));});
test('changing a style definition is picked up on a fresh preview while kept endpoints stay frozen',()=>{const h=host('alpha beta'),cfg=blendStyles(h,{pointSize:14},{pointSize:36}),p=new api.PreviewSession(h.target);p.preview(cfg);h.doc.allCharacterStyles[1].pointSize=48;p.preview(cfg);assert.equal(h.chars.at(-1).pointSize,48);p.keep(cfg);h.doc.allCharacterStyles[1].pointSize=60;p.preview(s({property:'skew',min:0,max:10}));assert.equal(h.chars.at(-1).pointSize,48);p.rollback();});
test('style blend supports Gaussian curves and restarting within words',()=>{const h=host('abcd efgh'),cfg=blendStyles(h,{pointSize:10,tracking:0},{pointSize:30,tracking:200});Object.assign(cfg,{mode:'character',restart:'word',curve:'gaussian',target:'letters'});const p=new api.PreviewSession(h.target);p.preview(cfg);assert.equal(h.chars[0].pointSize,10);assert.equal(h.chars[1].pointSize,30);assert.equal(h.chars[3].pointSize,10);assert.equal(h.chars[5].pointSize,10);assert.equal(h.chars[6].pointSize,30);p.rollback();});
test('style rotation blends use the short angular route and retain exact endpoints',()=>{const a={a:350,b:10,angle:true};assert.equal(api.styleBlendNumber(a,0),350);assert.equal(api.styleBlendNumber(a,50),360);assert.equal(api.styleBlendNumber(a,100),10);assert.equal(api.styleBlendNumber({a:-15,b:15,angle:true},50),0);});
test('style inheritance cycles are rejected and grouped paths can resolve remapped IDs',()=>{const a={id:101,name:'A'},b={id:102,name:'B'};a.basedOn=b;b.basedOn=a;assert.throws(()=>api.styleValue(a,'pointSize',{}),/cycle/);const group={name:'Group',constructor:{name:'CharacterStyleGroup'}},style={id:999,name:'A',parent:group};assert.equal(api.findBlendStyle({allCharacterStyles:[style]},101,'Group / A'),style);});
test('compatible variable axes blend simultaneously with numeric style values',()=>{const h=host('alpha beta'),font=h.chars[0].appliedFont,cfg=blendStyles(h,{appliedFont:font,designAxes:[100],pointSize:14},{appliedFont:font,designAxes:[900],pointSize:36}),p=new api.PreviewSession(h.target);p.preview(cfg);assert.equal(h.chars[0].designAxes[0],100);assert.equal(h.chars.at(-1).designAxes[0],900);assert.equal(h.chars.at(-1).pointSize,36);p.rollback();assert.ok(h.chars.every(c=>c.designAxes[0]===400));});
test('automatic underline and strikethrough colors roundtrip as native tokens',()=>{let restored=null;const span={start:0,end:0},story={characters:{itemByRange(){return{set underlineColor(v){restored=v;}};}}};const value=api.readProperty({underlineColor:'Text Color'},'underlineColor');assert.deepEqual(plain(value),{nativeColorString:'Text Color'});api.writeProperty(story,span,'underlineColor',value,{});assert.equal(restored,'Text Color');});
test('style blend UI selects style endpoints and applies all shared attributes',()=>{const h=uiHost();blendStyles(h,{pointSize:14,tracking:0},{pointSize:36,tracking:200});interaction=root=>{const property=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Tracking');property.selection=19;property.onChange();assert.ok(root.controls.some(c=>c.type==='button'&&c.text==='Blend attributes…'));assert.ok(root.controls.some(c=>typeof c.text==='string'&&c.text.includes('2 attributes')));const max=root.controls.filter(c=>c.type==='edittext')[2];max.text='75';max.onChanging();root.controls.find(c=>c.type==='button'&&c.text==='Apply').onClick();};const result=api.showDialog(h.target);assert.equal(result.settings.styleA,101);assert.equal(result.settings.styleB,102);assert.equal(h.chars.at(-1).pointSize,30.5);assert.equal(h.chars.at(-1).tracking,150);h.doc.undo();});
test('incompatible process and spot colors are reported while numeric attributes remain usable',()=>{const h=host('alpha beta'),rgb={id:1,name:'RGB',model:1,space:1,colorValue:[0,0,0]},spot={id:2,name:'Spot',model:2,space:1,colorValue:[100,0,0]},cfg=blendStyles(h,{pointSize:14,fillColor:rgb},{pointSize:36,fillColor:spot});let d=api.compileStyleBlend(h.doc,cfg);assert.deepEqual(plain(d.attributes.map(a=>a.id)),['pointSize']);assert.ok(d.ignored[0].includes('process colors'));h.doc.allCharacterStyles[1].fillColor={...rgb,id:2,name:'CMYK',space:2,colorValue:[0,0,0,0]};d=api.compileStyleBlend(h.doc,cfg);assert.equal(d.attributes.length,1);h.doc.allCharacterStyles[1].fillColor={...rgb,id:2,name:'RGB B',colorValue:[255,255,255]};assert.equal(api.compileStyleBlend(h.doc,cfg).attributes.length,2);});
test('saved style names take priority over IDs reassigned by an IDML roundtrip',()=>{const h=uiHost();h.doc.allCharacterStyles=[{id:999,name:'A',pointSize:14},{id:102,name:'B',pointSize:36},{id:101,name:'Other',pointSize:80}];h.doc.state.labels['TrackingRamp.v3.history']=JSON.stringify({version:3,effects:{styleBlend:{signature:api.signature(h.story),original:[],settings:{styleA:101,styleAName:'A',styleB:102,styleBName:'B'}}}});interaction=root=>{const property=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Tracking');property.selection=19;property.onChange();root.controls.find(c=>c.type==='button'&&c.text==='Apply').onClick();};const result=api.showDialog(h.target);assert.equal(result.settings.styleA,999);});
test('named variable-font instances are compatible when they share the same font file and axes',()=>{const h=host('alpha beta'),base=h.chars[0].appliedFont;Object.assign(base,{location:'/fonts/test-variable.otf',fontFamily:'Test'});const cfg=blendStyles(h,{appliedFont:{...base,name:'Test Thin'},designAxes:[100],pointSize:14},{appliedFont:{...base,name:'Test Black'},designAxes:[900],pointSize:36});const d=api.compileStyleBlend(h.doc,cfg);assert.equal(d.attributes.length,2);const p=new api.PreviewSession(h.target);p.preview(cfg);assert.equal(h.chars.at(-1).designAxes[0],900);p.rollback();});
test('style blends validate percentage ranges before writing and retain endpoint names',()=>{const h=host('alpha beta'),cfg=blendStyles(h,{pointSize:14},{pointSize:36}),before=JSON.stringify(h.doc.state);assert.throws(()=>new api.PreviewSession(h.target).preview({...cfg,min:-1}),/percentages/);assert.equal(JSON.stringify(h.doc.state),before);const result=new api.PreviewSession(h.target).commit(cfg);assert.equal(result.settings.styleAName,'A');assert.equal(result.settings.styleBName,'B');});

test('v8 one-sided skew and stroke resolve from the original text and Cancel restores them',()=>{const h=host('alpha beta gamma'),cfg=blendStyles(h,{}, {skew:20,strokeWeight:2});cfg.missingStyle='original';const before=JSON.stringify(h.doc.state),p=new api.PreviewSession(h.target);p.preview(cfg);assert.equal(h.chars[0].skew,0);assert.equal(h.chars[6].skew,10);assert.equal(h.chars.at(-1).skew,20);assert.equal(h.chars[6].strokeWeight,1);p.rollback();assert.equal(JSON.stringify(h.doc.state),before);});
test('v8 missing endpoints use mixed original values and preserve both-missing attributes',()=>{const h=host('alpha beta gamma');h.chars[6].skew=8;const cfg=blendStyles(h,{}, {skew:20});cfg.missingStyle='original';const p=new api.PreviewSession(h.target);p.preview(cfg);assert.equal(h.chars[6].skew,14);assert.equal(h.chars[7].skew,10);assert.ok(h.chars.every(c=>c.pointSize===24));p.rollback();});
test('v8 a committed stack stores settings on its story without compiled style endpoints',()=>{const h=host('alpha beta gamma'),p=new api.PreviewSession(h.target);p.keep(s({property:'skew',min:-10,max:20}));p.commit(s({max:90}));const saved=api.readSavedSetup(h.target);assert.equal(saved.status,'loaded');assert.deepEqual(plain(saved.recipe.stages.map(x=>x.settings.property)),['skew','tracking']);assert.equal(saved.recipe.stages[1].settings.max,90);});
test('v8 reopening and cancelling a saved setup changes neither formatting nor Undo history',()=>{const h=uiHost();new api.PreviewSession(h.target).commit(s({max:90}));const before=JSON.stringify(h.doc.state),history=h.doc.history.length;interaction=root=>{assert.equal(JSON.stringify(h.doc.state),before);assert.equal(h.doc.history.length,history);assert.ok(root.controls.some(c=>typeof c.text==='string'&&c.text.includes('Saved setup loaded')));const live=root.controls.find(c=>c.type==='checkbox'&&c.text==='Preview');assert.equal(live.value,false);root.controls.find(c=>c.type==='button'&&c.text==='Cancel').onClick();};api.showDialog(h.target);assert.equal(JSON.stringify(h.doc.state),before);assert.equal(h.doc.history.length,history);});
test('v8 saved setup detects edited text before attempting replacement',()=>{const h=host('alpha beta');new api.PreviewSession(h.target).commit(s());h.story.contents='edited text';const before=JSON.stringify(h.doc.state);const saved=api.readSavedSetup(h.target);assert.equal(saved.status,'blocked');assert.match(saved.message,/text changed/i);assert.equal(JSON.stringify(h.doc.state),before);});
test('v8 forgetting a setup preserves appearance, is undoable and stops automatic recall',()=>{const h=host('alpha beta');new api.PreviewSession(h.target).commit(s());const appearance=JSON.stringify(h.doc.state.characters);api.forgetSavedSetup(h.target);assert.equal(api.readSavedSetup(h.target).status,'none');assert.equal(JSON.stringify(h.doc.state.characters),appearance);h.doc.undo();assert.equal(api.readSavedSetup(h.target).status,'loaded');});

test('v8 saved stacks reread changed source styles and restore their complete original baseline',()=>{const h=host('alpha beta gamma'),cfg=blendStyles(h,{pointSize:14,tracking:0},{pointSize:36,tracking:200}),first=new api.PreviewSession(h.target);first.keep(cfg);first.commit(s({max:90}));h.doc.allCharacterStyles[1].pointSize=48;const saved=api.readSavedSetup(h.target),p=new api.PreviewSession(h.target),draft=p.load(saved.recipe);assert.equal(h.chars.at(-1).pointSize,36);p.preview(draft);assert.equal(h.chars.at(-1).pointSize,48);assert.equal(h.chars.at(-1).tracking,90);p.rollback();assert.equal(h.chars.at(-1).pointSize,36);p.commit(draft);assert.equal(h.chars.at(-1).pointSize,48);h.doc.undo();assert.equal(h.chars.at(-1).pointSize,36);});
test('v8 changing a recalled blend attribute subset restores attributes removed from its prior stack',()=>{const h=host('alpha beta gamma'),cfg=blendStyles(h,{pointSize:14,tracking:0},{pointSize:36,tracking:200}),first=new api.PreviewSession(h.target);first.commit(cfg);const p=new api.PreviewSession(h.target),draft=p.load(api.readSavedSetup(h.target).recipe);p.commit({...draft,styleAttributes:['pointSize']});assert.ok(h.chars.every(c=>c.tracking===0));assert.equal(h.chars.at(-1).pointSize,36);});
test('v8 recipes preserve saved highlighted bounds when reopened from their frame',()=>{const h=host('alpha beta gamma');h.target.scopes=[{kind:'selection',bounds:{start:6,end:9}},{kind:'story',bounds:{start:0,end:15}}];new api.PreviewSession(h.target).commit(s({max:50}));h.target.scopes=[{kind:'frame',bounds:{start:0,end:15}},{kind:'story',bounds:{start:0,end:15}}];const p=new api.PreviewSession(h.target),draft=p.load(api.readSavedSetup(h.target).recipe);assert.equal(p.target.scopes[draft.scope].kind,'selection');assert.deepEqual(plain(p.target.scopes[draft.scope].bounds),{start:6,end:9});p.preview({...draft,min:70,max:70});assert.ok(h.chars.slice(0,6).every(c=>c.tracking===0));assert.ok(h.chars.slice(10).every(c=>c.tracking===0));p.rollback();});
test('v8 another linked frame cannot silently claim a saved setup',()=>{const h=host('alpha beta');new api.PreviewSession(h.target).commit(s());const other={...h.target,frame:{id:99,extractLabel(){return '';}}};const saved=api.readSavedSetup(other);assert.equal(saved.status,'blocked');assert.match(saved.message,/another linked frame/i);});
test('v8 original-value inference is based on replacement baselines and does not accumulate',()=>{const h=host('alpha beta gamma'),cfg=blendStyles(h,{}, {skew:20});cfg.missingStyle='original';new api.PreviewSession(h.target).commit(cfg);new api.PreviewSession(h.target).commit({...cfg,max:50});assert.equal(h.chars[6].skew,5);assert.equal(h.chars.at(-1).skew,10);});
test('v8 Skip retains the earlier missing-endpoint rule',()=>{const h=host('alpha beta'),cfg=blendStyles(h,{pointSize:14},{pointSize:36,skew:20});cfg.missingStyle='skip';const d=api.compileStyleBlend(h.doc,cfg);assert.deepEqual(plain(d.attributes.map(a=>a.id)),['pointSize']);});
test('v8 bulk leading and color snapshots preserve automatic tokens without resolving characters',()=>{const columns=vm.runInContext('({leading:[18,777,18],fillColor:[{id:1,name:"Black"},{id:1,name:"Black"},"Text Color"]})',ctx);ctx.Leading={AUTO:777};const story={characters:{length:3,everyItem:()=>({...columns,getElements(){throw Error('Unnecessary scalar resolution');}})}};const rows=plain(api.takeSnapshot(story,['leading','fillColor']));assert.equal(rows[0].values.leading,18);assert.deepEqual(rows[1].values.leading,{automaticLeading:true});assert.deepEqual(rows[2].values.fillColor,{nativeColorString:'Text Color'});});
test('v8 scoped snapshots retain global indices while avoiding unrelated text',()=>{const h=host('alpha beta gamma'),rows=plain(api.takeSnapshot(h.story,['tracking'],{start:6,end:9}));assert.deepEqual(rows,[{start:6,end:9,values:{tracking:0}}]);});
test('v8 numeric-only kept style blends use an exact patch without recalculating the blend',()=>{const h=host('alpha beta gamma'),cfg=blendStyles(h,{pointSize:14,tracking:0},{pointSize:36,tracking:200}),p=new api.PreviewSession(h.target);p.keep(cfg);assert.ok(p.stages[0].patch);const before=h.chars.map(c=>c.pointSize);p.preview(s({property:'skew',min:-15,max:15}));assert.deepEqual(h.chars.map(c=>c.pointSize),before);p.rollback();});

test('v8 numeric bulk snapshots normalize native paragraph enumerators',()=>{const bulk=vm.runInContext('[{valueOf:function(){return 12345;}}]',ctx),story={characters:{length:1,everyItem:()=>({startParagraph:bulk,getElements(){throw Error('No scalar path needed');}})}};assert.deepEqual(plain(api.takeSnapshot(story,['startParagraph'])),[{start:0,end:0,values:{startParagraph:12345}}]);});
test('source avoids known ExtendScript reserved declarations',()=>{assert.doesNotMatch(source,/\b(?:var|function)\s+(?:abstract|boolean|byte|char|class|const|double|enum|export|extends|final|float|goto|implements|import|int|interface|long|native|package|private|protected|public|short|static|super|synchronized|throws|transient|volatile)\b/);});

test('v8 saved highlighted scopes are available in the reopened UI scope selector',()=>{const h=uiHost();h.target.scopes=[{kind:'selection',bounds:{start:6,end:9}},{kind:'story',bounds:{start:0,end:h.chars.length-1}}];new api.PreviewSession(h.target).commit(s({mode:'character',max:40}));h.target.scopes=[{kind:'frame',label:'Current frame',bounds:{start:0,end:h.chars.length-1}},{kind:'story',label:'Entire story',bounds:{start:0,end:h.chars.length-1}}];interaction=root=>{const labelIndex=root.controls.findIndex(c=>c.type==='statictext'&&c.text==='Scope'),scope=root.controls[labelIndex+1];assert.equal(scope.items[scope.selection.index],'Saved selection');root.controls.find(c=>c.type==='button'&&c.text==='Cancel').onClick();};api.showDialog(h.target);});
test('v8 inferred scale starts at 100 percent and a missing B returns to the original text',()=>{const h=host('alpha beta gamma'),cfg=blendStyles(h,{horizontalScale:160},{skew:20});cfg.missingStyle='original';const p=new api.PreviewSession(h.target);p.preview(cfg);assert.equal(h.chars[0].horizontalScale,160);assert.equal(h.chars[6].horizontalScale,130);assert.equal(h.chars.at(-1).horizontalScale,100);p.rollback();});
test('v8 explicit inherited values take priority over original-text fallback',()=>{const h=host('alpha beta gamma'),parent={id:100,name:'Parent',skew:8},cfg=blendStyles(h,{basedOn:parent},{skew:24});cfg.missingStyle='original';const p=new api.PreviewSession(h.target);p.preview(cfg);assert.equal(h.chars[0].skew,8);assert.equal(h.chars[6].skew,16);p.rollback();});

test('v8 saved baseline colors resolve their names when IDML reassigns swatch IDs',()=>{let restored;const oldID={id:1,name:'Other',isValid:true},named={id:999,name:'Ink',isValid:true},doc={swatches:{itemByID:()=>oldID,itemByName:()=>named}},story={characters:{itemByRange(){return{set fillColor(v){restored=v;}};}}};api.writeProperty(story,{start:0,end:0},'fillColor',{swatch:1,name:'Ink'},doc);assert.equal(restored,named);});

test('v8 a one-sided variable axis blends from the original compatible font vector',()=>{const h=host('alpha beta gamma'),font=h.chars[0].appliedFont,cfg=blendStyles(h,{}, {appliedFont:font,designAxes:[900],pointSize:36});cfg.missingStyle='original';const p=new api.PreviewSession(h.target);p.preview(cfg);assert.equal(h.chars[0].designAxes[0],400);assert.equal(h.chars[6].designAxes[0],650);assert.equal(h.chars.at(-1).designAxes[0],900);assert.equal(h.chars[0].pointSize,24);p.rollback();assert.ok(h.chars.every(c=>c.designAxes[0]===400));});

test('v8 recovers earlier single-property controls with preview off and a scope-review note',()=>{const h=uiHost();new api.PreviewSession(h.target).commit(s({property:'skew',min:-12,max:18}));delete h.doc.state.labels['TrackingRamp.v8.setup'];const before=JSON.stringify(h.doc.state),n=h.doc.history.length;interaction=root=>{const property=root.controls.find(c=>c.type==='dropdownlist'&&c.items?.[0]==='Tracking');assert.equal(property.selection.index,7);assert.ok(root.controls.some(c=>typeof c.text==='string'&&c.text.includes('review scope')));assert.equal(root.controls.find(c=>c.type==='checkbox'&&c.text==='Preview').value,false);assert.equal(JSON.stringify(h.doc.state),before);root.controls.find(c=>c.type==='button'&&c.text==='Cancel').onClick();};api.showDialog(h.target);assert.equal(h.doc.history.length,n);assert.equal(JSON.stringify(h.doc.state),before);});
test('v8 earlier multi-property data is explained without inventing an ordered setup',()=>{const h=uiHost(),p=new api.PreviewSession(h.target);p.keep(s({property:'skew',min:0,max:10}));p.commit(s({max:40}));delete h.doc.state.labels['TrackingRamp.v8.setup'];const saved=api.readSavedSetup(h.target);assert.equal(saved.status,'legacy');assert.equal(saved.settings,null);assert.match(saved.message,/order/i);});
test('v8 average graph uses all actual restart groups rather than the first short word',()=>{const p=api.makePlan(data('In fading memories'),s({mode:'character',restart:'word',target:'letters',property:'pointSize',curve:'gaussian',min:10,max:30}));const avg=api.averageDistribution(p);assert.equal(avg.average,true);assert.ok(Math.max(...avg.values)>10);assert.ok(Math.max(...avg.values)<30);assert.deepEqual(plain(p.groups[0].distribution.values),[10,10]);assert.equal(avg.values[0],10);assert.equal(avg.values.at(-1),10);});
test('v8 single group average preserves its assigned samples exactly',()=>{const p=api.makePlan(data('In'),s({mode:'character',restart:'word',property:'pointSize',curve:'gaussian',min:10,max:30}));assert.deepEqual(plain(api.averageDistribution(p).values),[10,10]);});
test('v8 paint-only style blend keeps a None-painted hidden stroke invisible and reversible',()=>{const h=host('alpha beta gamma'),none=h.doc.swatches.itemByID(2);none.name='None';h.chars.forEach(c=>{c.strokeColor=none;c.strokeWeight=1;});const cfg=blendStyles(h,{strokeColor:h.doc.swatches.itemByID(1)},{strokeColor:h.doc.swatches.itemByID(1)}),before=JSON.stringify(h.doc.state),p=new api.PreviewSession(h.target);p.preview(cfg);assert.ok(h.chars.every(c=>c.strokeColor.name==='None'&&c.strokeWeight===1));p.rollback();assert.equal(JSON.stringify(h.doc.state),before);});
test('v8 paint-only blend preserves a genuinely visible mixed stroke baseline',()=>{const h=host('alpha beta gamma'),ink=h.doc.swatches.itemByID(1);h.chars[6].strokeWeight=2;const cfg=blendStyles(h,{strokeColor:ink},{strokeColor:ink}),p=new api.PreviewSession(h.target);p.preview(cfg);assert.equal(h.chars[6].strokeWeight,2);assert.equal(h.chars[7].strokeWeight,0);p.rollback();});
test('v8 word blend assigns the same percentage to every character and following space in a word',()=>{const h=host('In fading memories'),cfg=blendStyles(h,{pointSize:10,skew:0,tracking:0},{pointSize:30,skew:20,tracking:100}),p=new api.PreviewSession(h.target),r=p.preview(cfg);for(let u=0;u<r.units.length;u++){const pct=r.distribution.values[u];for(const index of indices([r.units[u]])){assert.equal(h.chars[index].pointSize,10+20*pct/100);assert.equal(h.chars[index].skew,20*pct/100);assert.equal(h.chars[index].tracking,pct);}}p.rollback();});
test('v8 UI has exactly one bottom Preview checkbox, no Preview button, and always targets both',()=>{const h=uiHost();interaction=root=>{assert.equal(root.controls.filter(c=>c.type==='checkbox'&&c.text==='Preview').length,1);assert.equal(root.controls.filter(c=>c.type==='button'&&c.text==='Preview').length,0);assert.ok(!root.controls.some(c=>c.type==='dropdownlist'&&c.items?.[0]==='Letters'));root.controls.find(c=>c.type==='button'&&c.text==='Apply').onClick();};assert.equal(api.showDialog(h.target).settings.target,'both');});
test('v8 zero width plus missing width never invents stroke paint from a hidden original width',()=>{const h=host('alpha beta gamma'),none=h.doc.swatches.itemByID(2);none.name='None';none.model=0;h.chars.forEach(c=>{c.strokeColor=none;c.strokeWeight=1;});const cfg=blendStyles(h,{pointSize:14,strokeWeight:0},{pointSize:36});cfg.missingStyle='original';const p=new api.PreviewSession(h.target);p.preview(cfg);assert.ok(h.chars.every(c=>c.strokeColor.name==='None'),'No endpoint requests a visible stroke');p.rollback();});
test('v8 width-only styles do not invent paint when the original stroke is None',()=>{const h=host('alpha beta gamma'),none=h.doc.swatches.itemByID(2);none.name='None';none.model=0;h.chars.forEach(c=>{c.strokeColor=none;c.strokeWeight=0;});const cfg=blendStyles(h,{strokeWeight:0},{strokeWeight:2});cfg.missingStyle='original';const p=new api.PreviewSession(h.target);p.preview(cfg);assert.equal(h.chars[0].strokeColor.name,'None');assert.equal(h.chars[6].strokeWeight,1);assert.equal(h.chars.at(-1).strokeWeight,2);p.rollback();});
test('v8 explicit None endpoints suppress stroke even when widths are stored in both styles',()=>{const h=host('alpha beta gamma'),none=h.doc.swatches.itemByName('None'),ink=h.doc.swatches.itemByID(1);h.chars.forEach(c=>{c.strokeColor=ink;c.strokeWeight=2;});const cfg=blendStyles(h,{pointSize:14,strokeWeight:1,strokeColor:none},{pointSize:36,strokeWeight:2,strokeColor:none});cfg.missingStyle='original';const before=JSON.stringify(h.doc.state),p=new api.PreviewSession(h.target);p.preview(cfg);assert.ok(h.chars.every(c=>c.strokeColor.name==='None'));p.rollback();assert.equal(JSON.stringify(h.doc.state),before);});
test('v8 None to paint blends effective width from zero and preserves exact no-stroke endpoint',()=>{const h=host('alpha beta gamma'),none=h.doc.swatches.itemByName('None'),ink=h.doc.swatches.itemByID(1);const cfg=blendStyles(h,{strokeWeight:2,strokeColor:none},{strokeWeight:2,strokeColor:ink});cfg.missingStyle='original';const p=new api.PreviewSession(h.target);p.preview(cfg);assert.equal(h.chars[0].strokeColor.name,'None');assert.equal(h.chars[0].strokeWeight,0);assert.equal(h.chars[6].strokeWeight,1);assert.equal(h.chars.at(-1).strokeWeight,2);p.rollback();});
test('v8 a missing stroke width starts from visible zero when original paint is None',()=>{const h=host('alpha beta gamma'),none=h.doc.swatches.itemByName('None'),ink=h.doc.swatches.itemByID(1);h.chars.forEach(c=>{c.strokeColor=none;c.strokeWeight=1;});const cfg=blendStyles(h,{pointSize:14},{pointSize:36,strokeWeight:2,strokeColor:ink});cfg.missingStyle='original';const p=new api.PreviewSession(h.target);p.preview(cfg);assert.equal(h.chars[0].strokeColor.name,'None');assert.equal(h.chars[0].strokeWeight,0);assert.equal(h.chars[6].strokeWeight,1);p.rollback();assert.ok(h.chars.every(c=>c.strokeColor.name==='None'&&c.strokeWeight===1));});
test('v8 primary dropdowns use equal widths, aligned captions and concise choices',()=>{const h=uiHost();interaction=root=>{for(const label of ['Property','Scope','Values per','Restart','Curve']){const i=root.controls.findIndex(c=>c.type==='statictext'&&c.text===label),caption=root.controls[i],control=root.controls[i+1];assert.equal(caption.preferredSize.width,96);assert.equal(control.preferredSize.width,240);assert.ok(control.items.every(value=>!value.includes(' — ')));}root.controls.find(c=>c.type==='button'&&c.text==='Cancel').onClick();};api.showDialog(h.target);});
test('v8 matching latent positive widths without endpoint paint do not add a stroke',()=>{const h=host('alpha beta gamma'),none=h.doc.swatches.itemByName('None');h.chars.forEach(c=>{c.strokeColor=none;c.strokeWeight=1;});const cfg=blendStyles(h,{pointSize:14,strokeWeight:.64},{pointSize:36,strokeWeight:.64});cfg.missingStyle='original';const p=new api.PreviewSession(h.target);p.preview(cfg);assert.ok(h.chars.every(c=>c.strokeColor.name==='None'&&c.strokeWeight===.64));p.rollback();});
